library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity bbq_pulse_width_core is generic(WIDTH:positive:=32);port(clk,rst_n,signal_in:in std_logic;width_value:out std_logic_vector(WIDTH-1 downto 0);width_valid,overflow:out std_logic);end;
architecture rtl of bbq_pulse_width_core is signal prev:std_logic:='0';signal c,w:unsigned(WIDTH-1 downto 0):=(others=>'0');signal v,o:std_logic:='0';begin width_value<=std_logic_vector(w);width_valid<=v;overflow<=o;process(clk)begin if rising_edge(clk)then v<='0';if rst_n='0'then prev<='0';c<=(others=>'0');w<=(others=>'0');o<='0';else prev<=signal_in;if signal_in='1'then if c=(c'range=>'1')then o<='1';else c<=c+1;end if;elsif prev='1'then w<=c;c<=(others=>'0');v<='1';o<='0';else c<=(others=>'0');end if;end if;end if;end process;end architecture;
